const body = $input.first().json.body || {};

const tenant_id = body.tenant_id;
const user_id = body.user_id;
const redirect_uri = body.redirect_uri || $env.LICHESS_REDIRECT_URI;

// Validation
const errors = [];
if (!tenant_id) errors.push('tenant_id requis');
if (!user_id) errors.push('user_id requis');
if (!redirect_uri) errors.push('redirect_uri requis (ou configurer LICHESS_REDIRECT_URI)');

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

// Generate state token (includes user_id + tenant_id for callback)
const state = Buffer.from(JSON.stringify({
  tenant_id,
  user_id,
  ts: Date.now(),
  nonce: Math.random().toString(36).substring(2, 15)
})).toString('base64url');

// PKCE: Generate code_verifier and code_challenge
const crypto = require('crypto');
const code_verifier = crypto.randomBytes(32).toString('base64url');
const code_challenge = crypto
  .createHash('sha256')
  .update(code_verifier)
  .digest('base64url');

// Lichess OAuth scopes
const scopes = [
  'preference:read',
  'challenge:read',
  'challenge:write', 
  'puzzle:read',
  'team:read',
  'board:play'
].join(' ');

return {
  json: {
    valid: true,
    tenant_id,
    user_id,
    redirect_uri,
    state,
    code_verifier,
    code_challenge,
    scopes
  }
};

const input = $('Validate & Prepare').first().json;
const storeResult = $input.first().json;

if (storeResult.statusCode >= 400) {
  return {
    json: {
      success: false,
      error: { code: 500, message: 'Erreur stockage state', details: storeResult }
    }
  };
}

// Build Lichess authorization URL
const clientId = $env.LICHESS_CLIENT_ID;
if (!clientId) {
  return {
    json: {
      success: false,
      error: { code: 500, message: 'LICHESS_CLIENT_ID non configuré' }
    }
  };
}

const params = new URLSearchParams({
  response_type: 'code',
  client_id: clientId,
  redirect_uri: input.redirect_uri,
  scope: input.scopes,
  state: input.state,
  code_challenge: input.code_challenge,
  code_challenge_method: 'S256'
});

const authUrl = `https://lichess.org/oauth?${params.toString()}`;

// Store code_verifier in memory for callback (via state mapping)
// Note: In production, store code_verifier in Redis or similar
// For now, we embed it in state (less secure but functional)

return {
  json: {
    success: true,
    auth_url: authUrl,
    state: input.state,
    code_verifier: input.code_verifier,
    message: 'Redirigez l\'utilisateur vers auth_url pour autorisation Lichess'
  }
};

